const HATN = { mago: ['Sem capuz', 'Faixa do Aprendiz', 'Capuz Arcano', 'Coroa do Arquimago'], lanceiro: ['Sem capacete', 'Capacete de Ferro', 'Elmo de Cavaleiro', 'Elmo com Chifres'], arqueiro: ['Sem chapéu', 'Capuz do Caçador', 'Chapéu com Pena', 'Capuz do Patrulheiro'], guerreiro: ['Sem capacete', 'Capacete de Ferro', 'Elmo de Aço', 'Elmo de Cavaleiro'] };
const TOPN = ['Camisa de Camponês', 'Camisa da Classe', 'Colete Reforçado', 'Couraça'];
const LEGN = { m: ['Calça de Camponês', 'Calça da Classe', 'Calça com Joelheiras', 'Calça com Grevas'], f: ['Saia de Camponesa', 'Saia da Classe', 'Saia Reforçada', 'Saia Blindada'] };
const BOOTN = ['Botas de Camponês', 'Botas de Couro', 'Botas Altas', 'Botas de Aço'];
const SHN = ['Sem ombreiras', 'Ombreiras de Couro', 'Ombreiras de Ferro', 'Ombreiras de Aço'];
const GLN = ['Mãos nuas', 'Luvas de Couro', 'Manoplas de Ferro', 'Manoplas de Aço'];
const HAT_KIND = { mago: [null, 'wiz', 'wiz2', 'wiz3'], lanceiro: [null, 'iron', 'knight', 'horns'], arqueiro: [null, 'hood', 'feather', 'ranger'], guerreiro: [null, 'gw1', 'gw2', 'gw3'] };
const WCOST = [null, { wood: 60, stone: 40, hide: 10 }, { wood: 120, stone: 90, hide: 25 }, { wood: 220, stone: 160, hide: 45, gems: 3 }, { wood: 400, stone: 300, hide: 80, gems: 8 }];
const OCOST = t => { const c = { hide: 12 * t, food: 10 * t }; if (t >= 2) c.stone = 20 * t; if (t >= 3) c.gems = 2; return c; };
const SLOTS = { w: { max: 4, at: 'forge' }, h: { max: 3, at: 'tailor' }, t: { max: 3, at: 'tailor' }, l: { max: 3, at: 'tailor' }, b: { max: 3, at: 'tailor' }, s: { max: 3, at: 'forge' }, g: { max: 3, at: 'forge' } };
function clsProg() { return G.cls ? G.cp[G.cls] : null; }
function plv() { const c = clsProg(); return 1 + (c ? 1 + c.w + c.h + c.t + c.l + c.b + (c.s || 0) + (c.g || 0) : 0); }
function clsTitle() { const f = G.gender === 'f'; return G.cls ? (f ? CLASSES[G.cls].nf : CLASSES[G.cls].nm) : (f ? 'Camponesa' : 'Camponês'); }
function clsKind() { if (!G.cls) return null; let vt = G.cp[G.cls].w, st = ''; if (G.mag) { const w = magItem('w'), s = magItem(G.cls === 'mago' ? 'o' : 's'); if (w && w.vt != null) vt = w.vt; if (s && s.st != null) st = ':' + s.st; } return 'cls:' + G.cls + ':' + vt + st; }
function clsWeapon() { if (!G.cls) return null; const C = CLASSES[G.cls], t = G.cp[G.cls].w; return { id: 'cls', icon: C.icon, name: C.w[t], dmg: C.dmg[t], cd: C.cd, range: C.range, cls: G.cls, tier: t }; }
function clsBonus(kind) { /* bônus de coleta */ const c = clsProg(); if (!c) return 0; return 0; }
function slotName(slot, t) { const C = CLASSES[G.cls]; return slot === 'w' ? C.w[t] : slot === 'h' ? HATN[G.cls][t] : slot === 't' ? (t === 0 ? 'Camisa de ' + (G.gender === 'f' ? 'Camponesa' : 'Camponês') : t === 1 ? 'Camisa ' + (G.gender === 'f' ? C.nf : C.nm) : TOPN[t]) : slot === 'l' ? (t === 1 ? (G.gender === 'f' ? 'Saia' : 'Calça') + ' ' + (G.gender === 'f' ? C.nf : C.nm) : LEGN[G.gender === 'f' ? 'f' : 'm'][t]) : slot === 'b' ? BOOTN[t] : slot === 's' ? SHN[t] : GLN[t]; }
function slotCost(slot, t) { return slot === 'w' ? WCOST[t] : OCOST(t); }
function slotWhy(slot) {
  if (!G.cls) return 'Escolha uma classe'; const cur = G.cp[G.cls][slot], sp = SLOTS[slot]; if (cur >= sp.max) return 'ok';
  const nt = cur + 1; if (!countB(sp.at)) return 'Construa a ' + BT[sp.at].name;
  if (!G.workers.some(w => w.role === (sp.at === 'forge' ? 'smith' : 'artisan'))) return 'Contrate ' + (sp.at === 'forge' ? 'um Ferreiro' : 'um Artesão') + ' com o chefe';
  if (hallLv() < nt) return 'Requer Salão nível ' + nt;
  if (!canPay(slotCost(slot, nt))) return 'Faltam recursos';
  return '';
}
function slotEffect(slot, nt) {
  const c = G.cls;
  if (slot === 'w') {
    const C = CLASSES[c]; let e = 'dano ' + C.dmg[nt];
    if (c === 'mago') e += ` · ${[1, 2, 2, 3, 4][nt]} orbe${nt ? 's' : ''}` + (nt >= 2 ? ' · queimadura 🔥' : '') + (nt >= 3 ? ' · explosão 💥' : '') + (nt >= 4 ? ' · teleguiados 🎯' : '');
    if (c === 'lanceiro') e += ` · alcance ${(C.range + nt * .2).toFixed(1)}` + (nt >= 1 ? ' · atravessa inimigos' : '') + (nt >= 3 ? ' · golpe longo' : '') + ` · escudo −${[0, 5, 10, 15, 20][nt]}% dano`;
    if (c === 'arqueiro') e += ` · ${[1, 2, 2, 3, 5][nt]} flecha${nt ? 's' : ''}` + (nt >= 2 ? ' · veneno ☠️' : '') + (nt >= 3 ? ' · bombas 💣' : '') + (nt >= 4 ? ' · teleguiadas 🎯' : '');
    if (c === 'guerreiro') e += ` · escudo −${[0, 10, 20, 30, 40][nt]}% dano` + (nt >= 3 ? ' · golpe em área' : '');
    return e;
  }
  return slot === 'h' ? '+1,5 vida/s ao descansar' : slot === 't' ? '+15 vida · −4% dano recebido' : slot === 'l' ? '+10 vida' : slot === 'b' ? '+5% velocidade' : slot === 's' ? '+10 vida · −2% dano recebido' : '+6% de dano';
}
function chooseClass(c) {
  if (!CLASSES[c] || G.quest < 2) return false; G.cls = c; G.weapon = 'cls'; buildPlayer(); UI.refreshHotbar(); Sfx.build();
  Particles.emit(P.pos.x, P.pos.y + 2, P.pos.z, 50, { color: [0xffd23f, 0x7dff6a, 0xffffff], speed: 6, up: 8, life: 1.4, size: .4, area: .6 });
  UI.toast(`🌟 Agora você é ${clsTitle().toLowerCase().replace(/^./, m => m)} · Nível ${plv()}!`, 'good'); saveGame(); return true;
}
function evolveSlot(slot) {
  if (slotWhy(slot)) return false; const nt = G.cp[G.cls][slot] + 1; pay(slotCost(slot, nt)); G.cp[G.cls][slot] = nt;
  buildPlayer(); P.hp = P.maxHp; if (slot === 'w') G.weapon = 'cls'; UI.refreshHotbar(); Sfx.build();
  Particles.emit(P.pos.x, P.pos.y + 1.4, P.pos.z, 46, { color: [0xffd23f, 0xfff3b0, 0x7dff6a], speed: 5, up: 7, life: 1.2, size: .36, area: .5 });
  floatText(new T.Vector3(P.pos.x, P.pos.y + 3.2, P.pos.z), `⭐ Nível ${plv()}!`, '#ffd23f');
  UI.toast(`⭐ ${slotName(slot, nt)}! Você chegou ao Nível ${plv()}.`, 'good'); saveGame(); return true;
}

