const ROLE_MAX = { builder: 2, lumber: 2, miner: 2, farmer: 1, fisher: 1, hunter: 1, cook: 2, smith: 1, artisan: 1, guard: 4 };
const ROLE_NEED = { lumber: 'sawmill', miner: 'quarry', farmer: 'farm', hunter: 'lodge', cook: 'kitchen', smith: 'forge', artisan: 'tailor' };
const ROLE_DROP = { lumber: 'sawmill', miner: 'quarry', farmer: 'kitchen', fisher: 'kitchen', hunter: 'kitchen' };
let _rawAcc = { wood: 0, stone: 0 }, _rawFx = 0;
/* a máquina da serraria (e da pedreira) transforma toras/pedra bruta em tábuas/pedra pronta e manda para o armazém */
function rawTick(dt, t) {
  _rawFx -= dt;
  for (const [k, ty] of [['wood', 'sawmill'], ['stone', 'quarry']]) {
    const ps = G.plots.filter(p => p.type === ty && p.level > 0 && p.state === 'idle' && !p.damaged); if (!ps.length || G.raw[k] < 1 || G.res[k] >= capFor(k)) continue;
    const lv = ps.reduce((s, p) => s + p.level, 0); _rawAcc[k] += dt * (1.2 + .8 * lv);
    const n = Math.min(Math.floor(_rawAcc[k]), Math.floor(G.raw[k])); if (n >= 1) { _rawAcc[k] -= n; const got = addRes(k, n); G.raw[k] -= got; }
    if (_rawFx <= 0) { _rawFx = .45; const p0 = ps[0]; if (dist2({ x: p0.x, z: p0.z }, P.pos) < 900) { Particles.emit(p0.x + rnd(-1, 1), heightAt(p0.x, p0.z) + 1.6, p0.z + rnd(-1, 1), 4, { color: k === 'wood' ? [0xe8cf9a, 0xc9a26a] : [0xd0d0d0, 0x9a9a9a], speed: 1.5, up: 1.6, life: .6, size: .25 }); if (k === 'wood' && Math.random() < .5) Sfx.chop(); } }
  }
}
function hireWhy(role, c) {
  const cnt = G.workers.filter(w => w.role === role).length, mx = ROLE_MAX[role];
  if (mx != null && cnt >= mx) return 'Equipe completa (' + cnt + '/' + mx + ')';
  const need = ROLE_NEED[role]; if (need && !countB(need)) return 'Construa a ' + BT[need].name;
  if (!canPay(c)) return 'Faltam recursos'; return '';
}
function workDest(role) {
  const ty = ROLE_DROP[role]; if (!ty) return null; const p = G.plots.find(q => q.type === ty && q.level > 0 && q.state !== 'building' && !q.damaged); if (!p) return null;
  const a = Math.atan2(-p.x, -p.z); return { x: p.x + Math.sin(a) * 3.4, z: p.z + Math.cos(a) * 3.4 };
}
