/* ---------- Colisão ---------- */
var BRIDGE = null; /* {x,z,c,s,len,wd,y} — preenchido pelo CreekFX */
function bridgeUV(x, z) { const B = BRIDGE, dx = x - B.x, dz = z - B.z; return [dx * B.c + dz * B.s, -dx * B.s + dz * B.c]; }
function bridgeY(x, z) { /* altura do deck se (x,z) está sobre a ponte, senão null */
  if (!BRIDGE) return null; const [u, v] = bridgeUV(x, z), B = BRIDGE;
  if (Math.abs(v) > B.wd / 2 - .05 || Math.abs(u) > B.len / 2 + 1.6) return null;
  const e = Math.abs(u) - B.len / 2; /* rampa suave nas pontas, encontrando o terreno */
  if (e <= 0) return B.y;
  const h = heightAt(x, z); return Math.max(h, lerp(B.y, h, clamp(e / 1.6, 0, 1)));
}
function bridgeRail(x, z) { /* mureta: bloqueia as laterais do deck */
  if (!BRIDGE) return false; const [u, v] = bridgeUV(x, z), B = BRIDGE;
  return Math.abs(u) < B.len / 2 - .1 && Math.abs(v) > B.wd / 2 - .12 && Math.abs(v) < B.wd / 2 + .9;
}
function canStand(x, z) {
  if (x > 800) return realmStand(x, z);
  if (bridgeRail(x, z)) return false;
  if (x * x + z * z > WORLD_R * WORLD_R) return false;
  if (inWater(x, z) || (heightAt(x, z) < -.95 && bridgeY(x, z) == null)) return false;
  if (wallOn() && wallBlock(x, z)) return false;
  for (const c of colliders) if ((x - c.x) ** 2 + (z - c.z) ** 2 < c.r * c.r) return false;
  const cx = Math.floor(x / 6), cz = Math.floor(z / 6);
  for (let a = -1; a <= 1; a++)for (let b = -1; b <= 1; b++) { const l = treeGrid.get((cx + a) + ',' + (cz + b)); if (l) for (const t of l) if (t.alive && (t.x - x) ** 2 + (t.z - z) ** 2 < .8) return false; }
  for (const r of Rocks) if (r.alive && (r.x - x) ** 2 + (r.z - z) ** 2 < r.rad * r.rad) return false;
  return true;
}

function updateWorld(dt, t) {
  sky.position.copy(camera.position);
  waterMat.uniforms.t.value = t; water.position.y = WATER_Y + Math.sin(t * 1.2) * .02;
  for (const c of clouds) { c.position.x += c.userData.sp * dt; if (c.position.x > 280) c.position.x = -280; }
  updateTrees(dt); updateRocksBushes(dt);
}


/* ====================== DIA E NOITE: céu, luz, estrelas, lua, vaga-lumes, lobos ====================== */
const Sky = { t: .3, day: 1, night: 0, isNight: false, len: 420 };
