  sTop: new T.Color(0x3a4f9a), sMid: new T.Color(0xe08a5a), sHor: new T.Color(0xffb070),
  sunLo: new T.Color(0xffa860), sunHi: new T.Color(0xfff0cf),
  hDay: new T.Color(0xd8ecff), hNight: new T.Color(0x3a4a86), gDay: new T.Color(0x6a9a48), gNight: new T.Color(0x16241c),
  cDay: new T.Color(0xffffff), cNight: new T.Color(0x242c48),
