const _sk = new T.Color(), _sk2 = new T.Color();
function skyMix(out, d, n, s, day, dusk) { out.copy(n).lerp(d, day); return out.lerp(s, dusk * .7); }

const stars = (() => {
  const N = 900, pos = new Float32Array(N * 3);
  for (let i = 0; i < N; i++) { const a = Math.random() * 6.283, y = Math.random() * .95 + .02, r = Math.sqrt(1 - y * y); pos[i * 3] = Math.cos(a) * r * 480; pos[i * 3 + 1] = y * 480; pos[i * 3 + 2] = Math.sin(a) * r * 480; }
  const g = new T.BufferGeometry(); g.setAttribute('position', new T.BufferAttribute(pos, 3));
  const m = new T.Points(g, new T.PointsMaterial({ color: 0xffffff, size: 2.1, sizeAttenuation: false, transparent: true, opacity: 0, depthWrite: false, fog: false }));
  m.renderOrder = -9; m.frustumCulled = false; scene.add(m); return m;
})();
const moon = (() => {
  const g = new T.Group();
  const disc = new T.Mesh(new T.SphereGeometry(13, 20, 14), new T.MeshBasicMaterial({ color: 0xeef2ff, fog: false }));
  const cv = document.createElement('canvas'); cv.width = cv.height = 128; const x = cv.getContext('2d'), gr = x.createRadialGradient(64, 64, 6, 64, 64, 64);
  gr.addColorStop(0, 'rgba(200,220,255,.55)'); gr.addColorStop(1, 'rgba(200,220,255,0)'); x.fillStyle = gr; x.fillRect(0, 0, 128, 128);
  const halo = new T.Sprite(new T.SpriteMaterial({ map: new T.CanvasTexture(cv), transparent: true, depthWrite: false, fog: false })); halo.scale.set(120, 120, 1);
  for (const [px, py, r] of [[-3, 2, 2.6], [4, -3, 1.8], [2, 5, 1.3]]) { const c = new T.Mesh(new T.CircleGeometry(r, 12), new T.MeshBasicMaterial({ color: 0xcfd6ea, fog: false })); c.position.set(px, py, 12.9); g.add(c); }
  g.add(disc); g.add(halo); g.userData = { disc, halo }; g.renderOrder = -8; scene.add(g); return g;
})();

function skyClock() { const h = Sky.t * 24, hh = Math.floor(h), mm = Math.floor((h % 1) * 60); return String(hh).padStart(2, '0') + ':' + String(mm).padStart(2, '0'); }
let wasNight = false, howlT = 6;
