  sun.intensity = 1.5 * sstep(-.02, .3, e); sun.color.copy(SKC.sunLo).lerp(SKC.sunHi, sstep(.05, .55, e)); sun.visible = sun.intensity > .01;
  fill.intensity = .12 + .38 * night; fill.position.copy(SUN_DIR).negate().multiplyScalar(100); fill.position.y = Math.max(20, fill.position.y);
  hemi.intensity = .24 + .46 * day; hemi.color.copy(SKC.hNight).lerp(SKC.hDay, day); hemi.groundColor.copy(SKC.gNight).lerp(SKC.gDay, day);
