  if (night > .5 && G.started && Math.random() < dt * 16) { const ax = P.pos.x + rnd(-24, 24), az = P.pos.z + rnd(-24, 24); Particles.emit(ax, heightAt(ax, az) + rnd(.5, 2.6), az, 1, { color: [0xeaff6a, 0xb6ff4a, 0xfff49a], speed: .5, up: .1, life: 4, size: .26, grav: -.02 }); }
