    if (Sky.isNight && isFullMoon()) { startMoonCine(); setTimeout(() => UI.banner('🌕 LUA CHEIA!', 'Os lobos uivam... eles estão soltos! Um lobisomem ronda a floresta.'), 7600); howlT = 22; spawnNightWolves(true); }
    else if (Sky.isNight) { UI.banner('🌙 Anoiteceu', 'Lobos rondam a floresta. Fique perto da fogueira!'); Sfx.howl(); spawnNightWolves(); }
