  for (let i = 0; i < n; i++) { const a = rnd(0, 6.28), r = rnd(78, 150), x = Math.cos(a) * r, z = Math.sin(a) * r; if (!canStand(x, z) || nearVillage(x, z, 4)) continue; const w = spawnAnimal('wolf', x, z); w.night = true; w.aggro = true; if (full) { w.hp = w.maxHp = Math.round(w.maxHp * 1.4); w.dmgMul = 1.3; } }
