    const p = t.hide ? null : t.getPos(_pv);
    if (!p) { if (t._d !== 0) { t._d = 0; t.el.style.display = 'none'; } continue; }
    const d = camera.position.distanceTo(p);
    if (d > t.maxD) { if (t._d !== 0) { t._d = 0; t.el.style.display = 'none'; } continue; }
    p.project(camera);
