    if (t._d !== 1) { t._d = 1; t.el.style.display = ''; }
    t.el.style.transform = `translate(${((p.x * .5 + .5) * w).toFixed(1)}px,${((-p.y * .5 + .5) * h).toFixed(1)}px) translate(-50%,-100%)`;
