  if (!G.started) return;
  if (!Fest.said) { Fest.said = true; if (f !== 'none') UI.banner(FESTS[f].i + ' ' + FESTS[f].n + '!', FESTS[f].t); }
  Fest.hatT -= dt; if (Fest.hatT <= 0) { Fest.hatT = 3; festApplyHats(f); }
