  for (const b of Fest.bats) { b.a += dt * b.sp; const x = Math.cos(b.a) * b.r, z = 6 + Math.sin(b.a) * b.r; b.m.position.set(x, b.h + Math.sin(t * 2 + b.a * 3) * 1.2, z); b.m.rotation.y = -b.a; const fl = Math.sin(t * 14 + b.a * 5) * .7; b.p1.rotation.z = fl; b.p2.rotation.z = -fl; }
