/* ====================== LAGOA VIVA: margem, peixes saltando, patos, ondas ====================== */
const SHORE = [];
for (let i = 0; i < 28; i++) { const a = i / 28 * 6.283; let r = POND.r * 1.22; for (let k = 0; k < 8 && !canStand(POND.x + Math.cos(a) * r, POND.z + Math.sin(a) * r); k++) r += .8; const x = POND.x + Math.cos(a) * r, z = POND.z + Math.sin(a) * r; if (canStand(x, z) && Math.hypot(x, z) > 44) SHORE.push({ x, z }); }
const rings = [];
for (let i = 0; i < 10; i++) { const m = new T.Mesh(new T.RingGeometry(.6, .8, 24).rotateX(-Math.PI / 2), new T.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, fog: false, depthWrite: false })); m.visible = false; m.renderOrder = 4; scene.add(m); rings.push({ m, t: 0 }); }
