for (let i = 0; i < 7; i++) { const f = makeFish(pick([0xff9a3c, 0xffd23f, 0x6cc7ff, 0xff6b8a, 0xe8e8ee])); f.visible = false; scene.add(f); pondFish.push({ m: f, t: rnd(2, 12), a: 0, leap: 0, sx: 0, sz: 0, dx: 0, dz: 0 }); }
for (let i = 0; i < 4; i++) { const d = makeDuck(); const a = rnd(0, 6.28), r = rnd(2, POND.r * .7); d.position.set(POND.x + Math.cos(a) * r, WATER_Y + .02, POND.z + Math.sin(a) * r); d.scale.setScalar(1.3); scene.add(d); ducks.push({ m: d, a, r, w: rnd(.04, .1) * (i % 2 ? 1 : -1), ph: rnd(0, 6) }); }
