  for (const r of rings) if (r.t > 0) { r.t -= dt * .9; r.m.scale.setScalar(1 + (1 - r.t) * 5); r.m.material.opacity = Math.max(0, r.t) * .7; if (r.t <= 0) r.m.visible = false; }
