  for (const d of ducks) { d.a += d.w * dt; const rr = d.r + Math.sin(t * .3 + d.ph) * 1.2; d.m.position.set(POND.x + Math.cos(d.a) * rr, WATER_Y + .03 + Math.sin(t * 2 + d.ph) * .03, POND.z + Math.sin(d.a) * rr); d.m.rotation.y = -d.a + (d.w > 0 ? 0 : Math.PI); d.m.rotation.z = Math.sin(t * 1.7 + d.ph) * .05; }
