    gear: { cls, c: c ? { h: c.h, t: c.t, l: c.l, b: c.b, s: c.s || 0, g: c.g || 0 } : null, jr: eq.ring || 0, jn: eq.neck || 0, jb: eq.brace || 0, col: LK.gear != null ? LK.gear : null }
