  P.mount = h; h.mounted = true; h.aggro = false; P.task = null; P.moveTo = null; G.stats.rides++; Sfx.coin(); UI.toast('🐴 Você montou! Corra pela floresta. (E para descer)', 'good'); UI.refreshQuest(); $('#bDis').hidden = false;
