/* ---- pesca ---- */
const bobber = new T.Mesh(new T.SphereGeometry(.22, 10, 8), new T.MeshBasicMaterial({ color: 0xff3b3b })); bobber.visible = false; scene.add(bobber);
const bobTop = new T.Mesh(new T.SphereGeometry(.14, 8, 6), new T.MeshBasicMaterial({ color: 0xffffff })); bobTop.position.y = .16; bobber.add(bobTop);
