  const n = addRes('food', food); G.stats.fish++; Sfx.coin(); splashRing(f.x, f.z); Particles.emit(f.x, WATER_Y + .5, f.z, 14, { color: [0x9be7ff, 0xffffff], speed: 2.4, up: 4, life: .8, size: .3, grav: 8 });
  floatText(new T.Vector3(P.pos.x, P.pos.y + 2.4, P.pos.z), rare ? `🐠 Peixe dourado! +${n} 🍖` : `🐟 +${n} 🍖`, rare ? '#ffd23f' : '#bff');
  if (rare) { addRes('gems', 1); floatText(new T.Vector3(P.pos.x, P.pos.y + 3.2, P.pos.z), '+1 💎', '#9be7ff'); }
