      const R = w.tier >= 4 ? 3.8 : 2.7, ex = ent.pos.x, ez = ent.pos.z; Sfx.hammer && Sfx.hammer();
      Particles.emit(ex, ent.pos.y + .3, ez, w.tier >= 4 ? 26 : 14, { color: [0xd9ae70, 0xffffff, 0xffd23f], speed: 4.5, up: 2.5, life: .6, size: .35, area: R * .5 });
