  for (const V of Villages) if (V.ally) { const [a, b] = m2(V.x, V.z); mx.fillStyle = '#' + V.col.toString(16).padStart(6, '0'); mx.strokeStyle = V.under > 0 && Math.floor(performance.now() / 300) % 2 ? '#ff2020' : '#000'; mx.lineWidth = 3; mx.beginPath(); mx.rect(a - 7, b - 7, 14, 14); mx.fill(); mx.stroke(); }
  for (const c of Camps) { const [a, b] = m2(c.x, c.z); mx.fillStyle = c.cleared ? '#888' : '#d62828'; mx.beginPath(); mx.moveTo(a, b - 8); mx.lineTo(a + 8, b + 6); mx.lineTo(a - 8, b + 6); mx.closePath(); mx.fill(); mx.strokeStyle = '#000'; mx.lineWidth = 1.5; mx.stroke(); }
