function startGame(cont) {
  try {
  Sfx.init(); Sfx.click();
  if (cont) {
    for (const w of (SAVED.workers || [])) addWorker(w.role, w.name, w.female);
  } else {
    G.gender = pickedGender; G.name = ($('#nm').value || '').trim().slice(0, 14) || (pickedGender === 'f' ? 'Aline' : 'Aldo');
    addWorker('builder', 'Bento', false);
  }
  buildPlayer();
  if (cont && SAVED && SAVED.player && Number.isFinite(SAVED.player.x) && Number.isFinite(SAVED.player.z)) {
    P.pos.set(SAVED.player.x, Number.isFinite(SAVED.player.y) ? SAVED.player.y : heightAt(SAVED.player.x, SAVED.player.z), SAVED.player.z);
    P.yaw = Number.isFinite(SAVED.player.yaw) ? SAVED.player.yaw : Math.PI;
    if (SAVED.camera) {
      CAM.mode = ['first', 'third', 'aerial'].includes(SAVED.camera.mode) ? SAVED.camera.mode : 'third';
      if (Number.isFinite(SAVED.camera.yaw)) CAM.yaw = SAVED.camera.yaw;
      if (Number.isFinite(SAVED.camera.tp)) CAM.tp = SAVED.camera.tp;
      if (Number.isFinite(SAVED.camera.dist)) CAM.dist = clamp(SAVED.camera.dist, 3.5, 20);
      if (Number.isFinite(SAVED.camera.aerDist)) CAM.aerDist = clamp(SAVED.camera.aerDist, 18, 90);
    }
  } else { P.pos.set(0, heightAt(0, 13), 13); P.yaw = Math.PI; CAM.yaw = 0; }
  P.mesh.position.copy(P.pos); P.mesh.visible = true; CAM.init = false;
  $('#title').hidden = true; $('#hud').hidden = false; $('#joy').hidden = !TOUCH; G.started = true;
  $('#av') && ($('#av').textContent = G.gender === 'f' ? '👩‍🌾' : '🧑‍🌾');
  UI.refreshAll();
  UI.toast(cont ? `🌲 Bem-vind${G.gender === 'f' ? 'a' : 'o'} de volta, ${G.name}!` : `🌲 Olá, ${G.name}! Corte árvores e fale com o Chefe Aldrik.`, 'good');
  if (!cont) setTimeout(() => UI.toast('👑 O Chefe Aldrik está perto da fogueira. Clique nele!'), 2600);
  saveGame();
  } catch (err) {
    console.error('Falha ao iniciar A Vida na Floresta:', err);
    const msg = document.createElement('p');
    msg.id = 'startError';
    msg.style.cssText = 'color:#ffd6d6;background:#5b1d1d;padding:10px;border-radius:8px;margin:10px 0;font-size:14px;';
    msg.textContent = 'Não foi possível iniciar a aventura. Recarregue a página e tente novamente. Detalhe: ' + (err && err.message ? err.message : 'erro desconhecido');
    const card = $('#tcard');
    const old = $('#startError'); if (old) old.remove();
    card.appendChild(msg);
  }
}
